import json
import sys
sys.path.insert(0, '/logs/agent/sessions/skills/tufte-data-viz')

import base64
from pathlib import Path

# Read the data
with open('/app/benchmark/source_data.json', 'r') as f:
    data = json.load(f)

with open('/app/benchmark/task_input.json', 'r') as f:
    task = json.load(f)

countries = data['national_development']['data']

# Define axes with proper normalization
dimensions = [
    {'name': 'GDP per Capita (USD)', 'max': 90000},
    {'name': 'HDI', 'max': 1.0},
    {'name': 'Freedom Index', 'max': 100},
    {'name': 'Corruption Index', 'max': 100},
    {'name': 'CO2 per Capita (tons)', 'max': 22},
    {'name': 'Military Expenditure (% GDP)', 'max': 6.5},
    {'name': 'Internet Penetration (%)', 'max': 100}
]

# Color palette for income groups - muted categorical
income_colors = {
    'High': '#4e79a7',          # steel blue
    'Upper-Middle': '#f28e2b',  # tangerine
    'Lower-Middle': '#e15759',  # coral
    'Low': '#76b7b2'            # sage
}

# Build parallel coordinates data
parallel_data = []
for c in countries:
    parallel_data.append({
        'name': c['country'],
        'income_group': c['income_group'],
        'value': [
