# Build parallel coordinates data
parallel_data = []
for c in countries:
    parallel_data.append([
        c['gdp_per_capita_usd'],
        c['hdi'],
        c['freedom_index'],
        c['corruption_perceptions_index'],
        c['co2_emissions_per_capita_tons'],
        c['military_expenditure_pct_gdp'],
        c['internet_penetration_pct'],
        c['income_group']
